class Cache:
    def __init__(self):
        self._lock = threading.Lock()
        self._entries: dict[str, Entry] = {}

    def find(self, key: str) -> Entry:
        with self._lock:                   # one acquisition per component entry
            return self._find_impl(key)

    def _find_impl(self, key: str) -> Entry:   # lock already held
        if key not in self._entries:
            self._entries[key] = Entry(key)
        return self._entries[key]

class Cache:
    def __init__(self):
        self._lock = asyncio.Lock()
        self._entries: dict[str, Entry] = {}

    async def find(self, key: str) -> Entry:
        async with self._lock:             # fair, unowned, non-reentrant
            return self._find_impl(key)    # sync helper: lock held

    def _find_impl(self, key: str) -> Entry:
        return self._entries.setdefault(key, Entry(key))

